+'use client';
+
+import { useState, useEffect } from 'react';
+import { useForm } from 'react-hook-form';
+import { zodResolver } from '@hookform/resolvers/zod';
+import { useTranslations } from 'next-intl';
+import { useRouter } from 'next/navigation';
+import { toast } from 'sonner';
+
+import { CreateUserSchema, CreateUserFormValues } from '@/schemas';
+import {
+  Dialog,
+  DialogContent,
+  DialogDescription,
+  DialogHeader,
+  DialogTitle
+} from '@/components/ui/dialog';
+import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
+import { Button } from '@/components/ui/button';
+import { Input } from '@/components/ui/input';
+import {
+  Form,
+  FormControl,
+  FormField,
+  FormItem,
+  FormLabel,
+  FormMessage
+} from '@/components/ui/form';
+import { UserSelector } from '@/components/admin/user-selector';
+import LoadingButton from '@/components/button/loading-button';
+import { createUser } from '@/actions/admin/create-user';
+import { ERROR_IDS } from '@/constants/errorIds';
+import { CoinPoolWithAccess } from '@/data/admin/coin-pools';
+import { AdminRole } from '@/types/admin';
+
+type Mode = 'existing' | 'new';
+
+interface AssignAmbassadorDialogProps {
+  pool: CoinPoolWithAccess;
+  currentUserRole: AdminRole;
+  open: boolean;
+  onOpenChange: (open: boolean) => void;
+}
+
+export default function AssignAmbassadorDialog({
+  pool,
+  currentUserRole,
+  open,
+  onOpenChange
+}: AssignAmbassadorDialogProps) {
+  const t = useTranslations('admin.coinPoolManagement.assignAmbassador');
+  const tCreateUser = useTranslations('admin.users.createUser');
+  const tError = useTranslations('errors');
+  const tCommon = useTranslations('common');
+  const router = useRouter();
+
+  const isSystemAdmin = currentUserRole === 'system-admin';
+  const showExistingUserTab = isSystemAdmin;
+
+  const [mode, setMode] = useState<Mode>(
+    showExistingUserTab ? 'existing' : 'new'
+  );
+  const [ambassadorUserIds, setAmbassadorUserIds] = useState<string[]>([]);
+  const [isSubmittingExisting, setIsSubmittingExisting] = useState(false);
+  const [isSubmittingNew, setIsSubmittingNew] = useState(false);
+  const [ambassadorRoleId, setAmbassadorRoleId] = useState<string>('');
+
+  const form = useForm<CreateUserFormValues>({
+    resolver: zodResolver(CreateUserSchema),
+    defaultValues: {
+      name: '',
+      email: '',
+      password: '',
+      confirmPassword: '',
+      adminRoleId: '',
+      coinPoolPermission: pool.id
+    }
+  });
+
+  useEffect(() => {
+    if (open && showExistingUserTab) {
+      setMode('existing');
+    } else if (open) {
+      setMode('new');
+    }
+  }, [open, showExistingUserTab]);
+
+  useEffect(() => {
+    if (open) {
+      fetch('/api/admin/roles/assignable')
+        .then((res) => res.json())
+        .then(
+          (data: {
+            success?: boolean;
+            roles?: Array<{ id: string; name: string }>;
+          }) => {
+            if (data.success && data.roles) {
+              const role = data.roles.find((r) => r.name === 'ambassador');
+              if (role) setAmbassadorRoleId(role.id);
+            }
+          }
+        );
+    }
+  }, [open]);
+
+  const getErrorMessage = (errorId: string | undefined): string => {
+    if (!errorId) return t('error');
+    if (errorId === ERROR_IDS.NO_PERMISSION) return tError('NO_PERMISSION');
+    if (errorId === ERROR_IDS.COIN_POOL_ACCESS_UNAUTHORIZED)
+      return tError('LOGIN_REQUIRED');
+    return tError(errorId as Parameters<typeof tError>[0]);
+  };
+
+  const handleSubmitExisting = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setIsSubmittingExisting(true);
+    try {
+      const res = await fetch(`/api/admin/coin-pools/${pool.id}/ambassadors`, {
+        method: 'PATCH',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ userIds: ambassadorUserIds })
+      });
+      const data = await res.json();
+      if (!res.ok || !data.success) {
+        toast.error(getErrorMessage(data.error));
+        return;
+      }
+      toast.success(t('success'));
+      onOpenChange(false);
+      setAmbassadorUserIds([]);
+      router.refresh();
+    } catch {
+      toast.error(t('error'));
+    } finally {
+      setIsSubmittingExisting(false);
+    }
+  };
+
+  const handleSubmitNew = async (values: CreateUserFormValues) => {
+    if (!ambassadorRoleId) {
+      toast.error(tCreateUser('error.insufficientPermissions'));
+      return;
+    }
+    setIsSubmittingNew(true);
+    try {
+      const result = await createUser({
+        ...values,
+        adminRoleId: ambassadorRoleId,
+        coinPoolPermission: pool.id
+      });
+      if (result.error) {
+        toast.error(result.error);
+        return;
+      }
+      toast.success(tCreateUser('success.userCreated'));
+      onOpenChange(false);
+      form.reset({
+        ...form.getValues(),
+        name: '',
+        email: '',
+        password: '',
+        confirmPassword: ''
+      });
+      router.refresh();
+    } finally {
+      setIsSubmittingNew(false);
+    }
+  };
+
+  return (
+    <Dialog open={open} onOpenChange={onOpenChange}>
+      <DialogContent className="sm:max-w-[560px]">
+        <DialogHeader>
+          <DialogTitle>{t('title')}</DialogTitle>
+          <DialogDescription>
+            {pool.name || pool.email || pool.id}
+          </DialogDescription>
+        </DialogHeader>
+        {showExistingUserTab ? (
+          <Tabs value={mode} onValueChange={(v) => setMode(v as Mode)}>
+            <TabsList>
+              <TabsTrigger value="existing">{t('tabExisting')}</TabsTrigger>
+              <TabsTrigger value="new">{t('tabNew')}</TabsTrigger>
+            </TabsList>
+            <TabsContent value="existing">
+              <form onSubmit={handleSubmitExisting} className="space-y-4 mt-4">
+                <div>
+                  <label className="text-sm font-medium mb-2 block">
+                    {t('ambassadorLabel')}{' '}
+                    <span className="text-red-500">*</span>
+                  </label>
+                  <UserSelector
+                    multiple
+                    value={ambassadorUserIds}
+                    onValueChange={(v) =>
+                      setAmbassadorUserIds(Array.isArray(v) ? v : [])
+                    }
+                    placeholder={t('ambassadorPlaceholder')}
+                  />
+                </div>
+                <div className="flex justify-end gap-2 pt-2">
+                  <Button
+                    type="button"
+                    variant="outline"
+                    onClick={() => onOpenChange(false)}
+                    disabled={isSubmittingExisting}
+                  >
+                    {tCommon('button.cancel')}
+                  </Button>
+                  <LoadingButton
+                    type="submit"
+                    loading={isSubmittingExisting}
+                    disabled={
+                      ambassadorUserIds.length === 0 || isSubmittingExisting
+                    }
+                  >
+                    {tCommon('button.confirm')}
+                  </LoadingButton>
+                </div>
+              </form>
+            </TabsContent>
+            <TabsContent value="new">
+              <Form {...form}>
+                <form
+                  onSubmit={form.handleSubmit(handleSubmitNew)}
+                  className="space-y-4 mt-4"
+                >
+                  <FormField
+                    control={form.control}
+                    name="name"
+                    render={({ field }) => (
+                      <FormItem>
+                        <FormLabel>
+                          {tCreateUser('form.name')}{' '}
+                          <span className="text-red-500">*</span>
+                        </FormLabel>
+                        <FormControl>
+                          <Input
+                            placeholder={tCreateUser('form.namePlaceholder')}
+                            {...field}
+                          />
+                        </FormControl>
+                        <FormMessage />
+                      </FormItem>
+                    )}
+                  />
+                  <FormField
+                    control={form.control}
+                    name="email"
+                    render={({ field }) => (
+                      <FormItem>
+                        <FormLabel>
+                          {tCreateUser('form.email')}{' '}
+                          <span className="text-red-500">*</span>
+                        </FormLabel>
+                        <FormControl>
+                          <Input
+                            type="email"
+                            placeholder={tCreateUser('form.emailPlaceholder')}
+                            {...field}
+                          />
+                        </FormControl>
+                        <FormMessage />
+                      </FormItem>
+                    )}
+                  />
+                  <FormField
+                    control={form.control}
+                    name="password"
+                    render={({ field }) => (
+                      <FormItem>
+                        <FormLabel>
+                          {tCreateUser('form.password')}{' '}
+                          <span className="text-red-500">*</span>
+                        </FormLabel>
+                        <FormControl>
+                          <Input type="password" {...field} />
+                        </FormControl>
+                        <FormMessage />
+                      </FormItem>
+                    )}
+                  />
+                  <FormField
+                    control={form.control}
+                    name="confirmPassword"
+                    render={({ field }) => (
+                      <FormItem>
+                        <FormLabel>
+                          {tCreateUser('form.confirmPassword')}{' '}
+                          <span className="text-red-500">*</span>
+                        </FormLabel>
+                        <FormControl>
+                          <Input type="password" {...field} />
+                        </FormControl>
+                        <FormMessage />
+                      </FormItem>
+                    )}
+                  />
+                  <div className="flex justify-end gap-2 pt-2">
+                    <Button
+                      type="button"
+                      variant="outline"
+                      onClick={() => onOpenChange(false)}
+                      disabled={isSubmittingNew}
+                    >
+                      {tCommon('button.cancel')}
+                    </Button>
+                    <LoadingButton
+                      type="submit"
+                      loading={isSubmittingNew || !ambassadorRoleId}
+                      disabled={!ambassadorRoleId || isSubmittingNew}
+                    >
+                      {tCreateUser('button.create')}
+                    </LoadingButton>
+                  </div>
+                </form>
+              </Form>
+            </TabsContent>
+          </Tabs>
+        ) : (
+          <Form {...form}>
+            <form
+              onSubmit={form.handleSubmit(handleSubmitNew)}
+              className="space-y-4 mt-4"
+            >
+              <FormField
+                control={form.control}
+                name="name"
+                render={({ field }) => (
+                  <FormItem>
+                    <FormLabel>
+                      {tCreateUser('form.name')}{' '}
+                      <span className="text-red-500">*</span>
+                    </FormLabel>
+                    <FormControl>
+                      <Input
+                        placeholder={tCreateUser('form.namePlaceholder')}
+                        {...field}
+                      />
+                    </FormControl>
+                    <FormMessage />
+                  </FormItem>
+                )}
+              />
+              <FormField
+                control={form.control}
+                name="email"
+                render={({ field }) => (
+                  <FormItem>
+                    <FormLabel>
+                      {tCreateUser('form.email')}{' '}
+                      <span className="text-red-500">*</span>
+                    </FormLabel>
+                    <FormControl>
+                      <Input
+                        type="email"
+                        placeholder={tCreateUser('form.emailPlaceholder')}
+                        {...field}
+                      />
+                    </FormControl>
+                    <FormMessage />
+                  </FormItem>
+                )}
+              />
+              <FormField
+                control={form.control}
+                name="password"
+                render={({ field }) => (
+                  <FormItem>
+                    <FormLabel>
+                      {tCreateUser('form.password')}{' '}
+                      <span className="text-red-500">*</span>
+                    </FormLabel>
+                    <FormControl>
+                      <Input type="password" {...field} />
+                    </FormControl>
+                    <FormMessage />
+                  </FormItem>
+                )}
+              />
+              <FormField
+                control={form.control}
+                name="confirmPassword"
+                render={({ field }) => (
+                  <FormItem>
+                    <FormLabel>
+                      {tCreateUser('form.confirmPassword')}{' '}
+                      <span className="text-red-500">*</span>
+                    </FormLabel>
+                    <FormControl>
+                      <Input type="password" {...field} />
+                    </FormControl>
+                    <FormMessage />
+                  </FormItem>
+                )}
+              />
+              <div className="flex justify-end gap-2 pt-2">
+                <Button
+                  type="button"
+                  variant="outline"
+                  onClick={() => onOpenChange(false)}
+                  disabled={isSubmittingNew}
+                >
+                  {tCommon('button.cancel')}
+                </Button>
+                <LoadingButton
+                  type="submit"
+                  loading={isSubmittingNew || !ambassadorRoleId}
+                  disabled={!ambassadorRoleId || isSubmittingNew}
+                >
+                  {tCreateUser('button.create')}
+                </LoadingButton>
+              </div>
+            </form>
+          </Form>
+        )}
+      </DialogContent>
+    </Dialog>
+  );
+}
