diff --git a/app/api/admin/coin-pools/[coinPoolId]/ambassadors/route.ts b/app/api/admin/coin-pools/[coinPoolId]/ambassadors/route.ts
new file mode 100644
index 0000000..fac1272
--- /dev/null
