+'use client';
+
+import React, { useState, useEffect } from 'react';
+import { useTranslations } from 'next-intl';
+import { UserCheck } from 'lucide-react';
+
+import { Select, SelectTrigger } from '@/components/ui/select';
+import { MultiCombobox } from '@/components/ui/comboBox';
+
+interface Ambassador {
+  id: string;
+  name: string | null;
+  email: string | null;
+}
+
+interface AmbassadorMultiSelectorProps {
+  value?: string[];
+  onValueChange: (value: string[]) => void;
+  placeholder?: string;
+  className?: string;
+  disabled?: boolean;
+  required?: boolean;
+  label?: string;
+}
+
+export default function AmbassadorMultiSelector({
+  value = [],
+  onValueChange,
+  placeholder,
+  className,
+  disabled = false,
+  required = false,
+  label
+}: AmbassadorMultiSelectorProps) {
+  const tAdmin = useTranslations('admin');
+  const tCommon = useTranslations('common');
+
+  const [ambassadors, setAmbassadors] = useState<Ambassador[]>([]);
+  const [isLoading, setIsLoading] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+  const defaultLabel = tAdmin('ambassadorSelector.label');
+  const defaultPlaceholder =
+    placeholder || tAdmin('ambassadorSelector.placeholder');
+
+  const fetchAmbassadors = async () => {
+    setIsLoading(true);
+    setError(null);
+    try {
+      const response = await fetch('/api/admin/users/ambassadors');
+      const data = await response.json();
+      if (data.success) {
+        setAmbassadors(data.users);
+      } else {
+        setError(data.error || tAdmin('ambassadorSelector.error'));
+      }
+    } catch (err) {
+      console.error('Failed to fetch ambassadors:', err);
+      setError(tAdmin('ambassadorSelector.error'));
+    } finally {
+      setIsLoading(false);
+    }
+  };
+
+  useEffect(() => {
+    fetchAmbassadors();
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, []);
+
+  const options = ambassadors.map((amb) => ({
+    value: amb.id,
+    label: amb.name || amb.email || 'No Name'
+  }));
+
+  const renderOption = (option: { value: string; label: string }) => {
+    const amb = ambassadors.find((a) => a.id === option.value);
+    return (
+      <div className="flex flex-col w-full">
+        <span className="break-words whitespace-normal font-medium">
+          {option.label}
+        </span>
+        {amb?.email && (
+          <span className="text-xs text-gray-500 break-words whitespace-normal">
+            {amb.email}
+          </span>
+        )}
+      </div>
+    );
+  };
+
+  const renderSelectedItems = () => {
+    if (value.length === 0) {
+      return (
+        <span className="text-muted-foreground">{defaultPlaceholder}</span>
+      );
+    }
+    if (value.length === 1) {
+      const amb = ambassadors.find((a) => a.id === value[0]);
+      return amb?.name || amb?.email || '';
+    }
+    return tCommon('select.itemsSelected', { count: value.length });
+  };
+
+  if (isLoading) {
+    return (
+      <div className="space-y-2">
+        {label && (
+          <label className="text-sm font-medium text-gray-700">
+            {label || defaultLabel}
+            {required && <span className="text-red-500 ml-1">*</span>}
+          </label>
+        )}
+        <Select value="" onValueChange={() => {}} disabled={true}>
+          <SelectTrigger className={className}>
+            <div className="flex items-center gap-2">
+              <UserCheck className="w-4 h-4" />
+              {tCommon('loading')}
+            </div>
+          </SelectTrigger>
+        </Select>
+      </div>
+    );
+  }
+
+  if (error) {
+    return (
+      <div className="space-y-2">
+        {label && (
+          <label className="text-sm font-medium text-gray-700">
+            {label}
+            {required && <span className="text-red-500 ml-1">*</span>}
+          </label>
+        )}
+        <Select value="" onValueChange={() => {}} disabled={true}>
+          <SelectTrigger className={className}>
+            <div className="flex items-center gap-2">
+              <UserCheck className="w-4 h-4" />
+              <span className="text-red-500">{error}</span>
+            </div>
+          </SelectTrigger>
+        </Select>
+      </div>
+    );
+  }
+
+  return (
+    <div className="space-y-2">
+      {label && (
+        <label className="text-sm font-medium text-gray-700">
+          {label || defaultLabel}
+          {required && <span className="text-red-500 ml-1">*</span>}
+        </label>
+      )}
+      <MultiCombobox
+        options={options}
+        value={value}
+        onValueChange={onValueChange}
+        placeholder={defaultPlaceholder}
+        className={className}
+        isLoading={disabled}
+        renderOption={renderOption}
+        renderSelectedItems={renderSelectedItems}
+        maxDisplayCount={2}
+        showSearch={true}
+        searchPlaceholder={tCommon('select.search', {
+          defaultMessage: '搜尋大使...'
+        })}
+        icon={<UserCheck className="w-4 h-4" />}
+        showClearButton={true}
+      />
+    </div>
+  );
+}
