+import { UserCheck, X } from 'lucide-react';
+
+import {
+  Select,
+  SelectContent,
+  SelectItem,
+  SelectTrigger
+} from '@/components/ui/select';
+
+interface Ambassador {
+  id: string;
+  name: string | null;
+  email: string | null;
+}
+
+interface AmbassadorSelectorProps {
+  value?: string;
+  onValueChange: (value: string) => void;
+  label?: string;
+  placeholder?: string;
+  className?: string;
+  disabled?: boolean;
+  required?: boolean;
+}
+
+export default function AmbassadorSelector({
+  value = '',
+  onValueChange,
+  label,
+  placeholder,
+  className,
+  disabled = false,
+  required = false
+}: AmbassadorSelectorProps) {
+  const t = useTranslations('common');
+  const tAdmin = useTranslations('admin');
+
+  const [ambassadors, setAmbassadors] = useState<Ambassador[]>([]);
+  const [isLoading, setIsLoading] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+
+  const defaultLabel = tAdmin('ambassadorSelector.label');
+  const defaultPlaceholder = tAdmin('ambassadorSelector.placeholder');
+
+  const fetchAmbassadors = async () => {
+    setIsLoading(true);
+    setError(null);
+    try {
+      const response = await fetch('/api/admin/users/ambassadors');
+      const data = await response.json();
+      if (data.success) {
+        setAmbassadors(data.users);
+      } else {
+        setError(data.error || tAdmin('ambassadorSelector.error'));
+      }
+    } catch (err) {
+      console.error('Failed to fetch ambassadors:', err);
+      setError(tAdmin('ambassadorSelector.error'));
+    } finally {
+      setIsLoading(false);
+    }
+  };
+
+  useEffect(() => {
+    fetchAmbassadors();
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, []);
+
+  if (isLoading) {
+    return (
+      <div className="space-y-2">
+        {label && (
+          <label className="text-sm font-medium text-gray-700">
+            {label || defaultLabel}
+            {required && <span className="text-red-500 ml-1">*</span>}
+          </label>
+        )}
+        <Select value="" onValueChange={() => {}} disabled={true}>
+          <SelectTrigger className={className}>
+            <div className="flex items-center gap-2">
+              <UserCheck className="w-4 h-4" />
+              {t('loading')}
+            </div>
+          </SelectTrigger>
+        </Select>
+      </div>
+    );
+  }
+
+  if (error) {
+    return (
+      <div className="space-y-2">
+        {label && (
+          <label className="text-sm font-medium text-gray-700">
+            {label}
+            {required && <span className="text-red-500 ml-1">*</span>}
+          </label>
+        )}
+        <Select value="" onValueChange={() => {}} disabled={true}>
+          <SelectTrigger className={className}>
+            <div className="flex items-center gap-2">
+              <UserCheck className="w-4 h-4" />
+              <span className="text-red-500">{error}</span>
+            </div>
+          </SelectTrigger>
+        </Select>
+      </div>
+    );
+  }
+
+  if (ambassadors.length === 0) {
+    return (
+      <div className="space-y-2">
+        {label && (
+          <label className="text-sm font-medium text-gray-700">
+            {label}
+            {required && <span className="text-red-500 ml-1">*</span>}
+          </label>
+        )}
+        <Select value="" onValueChange={() => {}} disabled={true}>
+          <SelectTrigger className={className}>
+            <div className="flex items-center gap-2">
+              <UserCheck className="w-4 h-4" />
+              <span className="text-gray-500">
+                {tAdmin('ambassadorSelector.noData')}
+              </span>
+            </div>
+          </SelectTrigger>
+        </Select>
