+          </div>
+        </SelectTrigger>
+        <SelectContent className="z-[10001] max-h-[200px] overflow-y-auto">
+          {ambassadors.map((amb) => (
+            <SelectItem key={amb.id} value={amb.id}>
+              <div className="flex flex-col w-full">
+                <span className="break-words whitespace-normal">
+                  {amb.name || amb.email}
+                </span>
+                {amb.email && (
+                  <span className="text-xs text-gray-500">{amb.email}</span>
+                )}
+              </div>
+            </SelectItem>
+          ))}
+        </SelectContent>
+      </Select>
+    </div>
+  );
+}
