+'use client';
+
+import { useTranslations } from 'next-intl';
+
+import { Badge } from '@/components/ui/badge';
+import { TooltipIcon } from '@/components/common/tooltip-icon';
+import type { ReservedByInviteCode } from '@/data/admin/coin-pools';
+
+interface AvailableBalanceCellProps {
+  tokenBalance: number;
+  availableBalance: number;
+  reservedByInviteCodes: ReservedByInviteCode[];
+}
+
+/**
+ * 代幣池列表中的「可用餘額」儲存格：顯示數字，若與代幣餘額不同則橘色並附邀請碼預留說明 tooltip。
+ */
+export function AvailableBalanceCell({
+  tokenBalance,
+  availableBalance,
+  reservedByInviteCodes
+}: AvailableBalanceCellProps) {
+  const tReserved = useTranslations(
+    'admin.coinPoolManagement.table.reservedByInviteCodes'
+  );
+  const showReservedTooltip =
+    availableBalance !== tokenBalance && reservedByInviteCodes.length > 0;
+
+  return (
+    <div className="flex items-center gap-1">
+      <span
+        className={`font-mono text-sm ${
+          availableBalance < 0
+            ? 'text-destructive font-medium'
+            : availableBalance !== tokenBalance
+              ? 'text-orange-600 dark:text-orange-400 font-medium'
+              : ''
+        }`}
+      >
+        {availableBalance.toLocaleString()}
+      </span>
+      {showReservedTooltip && (
+        <TooltipIcon
+          content={
+            <div className="space-y-1">
+              <div className="font-medium">{tReserved('label')}</div>
+              <ul className="list-none space-y-1 text-xs">
+                {reservedByInviteCodes.map(({ code, reserved }) => (
+                  <li key={code} className="flex items-center gap-1">
+                    <Badge
+                      variant='secondary'
+                      className="font-mono font-normal"
+                    >
+                      {code}
+                    </Badge>
+                    <span className="text-muted-foreground">
+                      {reserved.toLocaleString()}
+                    </span>
+                  </li>
+                ))}
+              </ul>
+            </div>
+          }
+          side="top"
+          aria-label={tReserved('ariaLabel')}
+        />
+      )}
+    </div>
+  );
+}
