@@ -0,0 +1,138 @@
+import { NextResponse } from 'next/server';
+
+import { getCurrentUserAdminRoles } from '@/data/admin/roles';
+import { currentUser } from '@/lib/auth';
+import prisma from '@/lib/prisma';
+import { ERROR_IDS } from '@/constants/errorIds';
+
+/**
+ * 取得大使用戶列表
+ * 根據當前用戶角色返回不同的列表：
+ * - system-admin: 所有大使
+ * - business-admin: 自己擁有 CoinPoolAccess 權限的代幣池下的大使
+ * - coin-pool-admin: 自己代表的代幣池下的大使
+ * - ambassador: 僅自己
+ * - 其他角色: 403
+ */
+export async function GET() {
+  try {
+    const currentUserRoles = await getCurrentUserAdminRoles();
+    if (currentUserRoles.length === 0) {
+      return NextResponse.json(
+        { error: ERROR_IDS.NO_PERMISSION },
+        { status: 403 }
+      );
+    }
+
+    const adminUser = await currentUser();
+    if (!adminUser?.id) {
+      return NextResponse.json(
+        { error: ERROR_IDS.LOGIN_REQUIRED },
+        { status: 403 }
+      );
+    }
+
+    const currentRole = currentUserRoles[0].name;
+    let ambassadors: Array<{
+      id: string;
+      name: string | null;
+      email: string | null;
+    }> = [];
+
+    if (currentRole === 'system-admin') {
+      ambassadors = await prisma.user.findMany({
+        where: {
+          userAdminRoles: {
+            some: {
+              adminRole: { name: 'ambassador' }
+            }
+          }
+        },
+        select: {
+          id: true,
+          name: true,
+          email: true
+        }
+      });
+    } else if (currentRole === 'business-admin') {
+      // 自己擁有 CoinPoolAccess 權限的代幣池下的大使
+      ambassadors = await prisma.user.findMany({
+        where: {
+          userAdminRoles: {
+            some: {
+              adminRole: { name: 'ambassador' }
+            }
+          },
+          coinPoolAccessUser: {
+            some: {
+              coinPool: {
+                coinPoolAccess: {
+                  some: { userId: adminUser.id }
+                }
+              }
+            }
+          }
+        },
+        select: {
+          id: true,
+          name: true,
+          email: true
+        }
+      });
+    } else if (currentRole === 'coin-pool-admin') {
+      // 自己代表的代幣池（coinPoolId = 自己 id）下的大使
+      ambassadors = await prisma.user.findMany({
+        where: {
+          userAdminRoles: {
+            some: {
+              adminRole: { name: 'ambassador' }
+            }
+          },
+          coinPoolAccessUser: {
+            some: { coinPoolId: adminUser.id }
+          }
+        },
+        select: {
+          id: true,
+          name: true,
+          email: true
+        }
+      });
+    } else if (currentRole === 'ambassador') {
+      const self = await prisma.user.findUnique({
+        where: {
+          id: adminUser.id,
+          userAdminRoles: {
+            some: {
+              adminRole: { name: 'ambassador' }
+            }
+          }
+        },
+        select: {
+          id: true,
+          name: true,
+          email: true
+        }
+      });
+      if (self) {
+        ambassadors = [self];
+      }
+    } else {
+      return NextResponse.json(
+        { error: ERROR_IDS.NO_PERMISSION },
+        { status: 403 }
+      );
+    }
+
+    return NextResponse.json({
+      success: true,
+      users: ambassadors
+    });
+  } catch (error) {
+    console.error('getAmbassadorsError:', error);
+    return NextResponse.json(
+      { error: 'getAmbassadorsError' },
+      { status: 500 }
+    );
+  }
+}
