+              <span className="text-red-500">{error}</span>
+            </div>
+          </SelectTrigger>
+        </Select>
+      </div>
+    );
+  }
+
+  if (ambassadors.length === 0) {
+    return (
+      <div className="space-y-2">
+        {label && (
+          <label className="text-sm font-medium text-gray-700">
+            {label}
+            {required && <span className="text-red-500 ml-1">*</span>}
+          </label>
+        )}
+        <Select value="" onValueChange={() => {}} disabled={true}>
+          <SelectTrigger className={className}>
+            <div className="flex items-center gap-2">
+              <UserCheck className="w-4 h-4" />
+              <span className="text-gray-500">
+                {tAdmin('ambassadorSelector.noData')}
+              </span>
+            </div>
+          </SelectTrigger>
+        </Select>
+      </div>
+    );
+  }
+
+  const selected = ambassadors.find((a) => a.id === value);
+
+  return (
+    <div className="space-y-2">
+      {label && (
+        <label className="text-sm font-medium text-gray-700">
+          {label}
+          {required && <span className="text-red-500 ml-1">*</span>}
+        </label>
+      )}
+      <Select value={value} onValueChange={onValueChange} disabled={disabled}>
+        <SelectTrigger className={className}>
+          <div className="flex items-center gap-2 justify-between w-full">
+            <div className="flex items-center gap-2">
+              <UserCheck className="w-4 h-4" />
+              {selected ? (
+                <div className="flex flex-col text-left">
+                  <span className="break-words whitespace-normal">
+                    {selected.name || selected.email}
+                  </span>
+                </div>
+              ) : (
+                <span className="text-gray-500">
+                  {placeholder || defaultPlaceholder}
+                </span>
+              )}
+            </div>
+            {!required && value && !disabled && (
+              <button
+                type="button"
+                aria-label={t('button.clear') || 'Clear'}
+                title={t('button.clear') || 'Clear'}
+                className="w-5 h-5 inline-flex items-center justify-center p-1 rounded-full bg-gray-100 hover:bg-gray-200 focus:outline-none transition-all 0.3s mr-1"
+                onPointerDown={(e) => e.stopPropagation()}
+                onClick={(e) => {
+                  e.stopPropagation();
+                  onValueChange('');
+                }}
+              >
+                <X className="w-4 h-4 text-gray-500" />
+              </button>
+            )}
+          </div>
+        </SelectTrigger>
+        <SelectContent className="z-[10001] max-h-[200px] overflow-y-auto">
+          {ambassadors.map((amb) => (
+            <SelectItem key={amb.id} value={amb.id}>
+              <div className="flex flex-col w-full">
+                <span className="break-words whitespace-normal">
+                  {amb.name || amb.email}
+                </span>
+                {amb.email && (
+                  <span className="text-xs text-gray-500">{amb.email}</span>
+                )}
+              </div>
+            </SelectItem>
+          ))}
+        </SelectContent>
+      </Select>
+    </div>
+  );
+}
